function r(i,t="full"){if(!i)return"";const e=new Date(i),n={full:{year:"numeric",month:"long",day:"numeric"},short:{year:"numeric",month:"2-digit",day:"2-digit"},time:{hour:"2-digit",minute:"2-digit"},datetime:{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}};return e.toLocaleDateString("es-ES",n[t]||n.full)}function o(i){return i?new Date(i).toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"}):""}function u(i,t="USD"){return i==null?"0.00":new Intl.NumberFormat("es-ES",{minimumFractionDigits:2,maximumFractionDigits:2}).format(i)}export{o as a,r as b,u as f};
